TEST(Macros, VersionStringsAreTheLibrarys) {
    EXPECT_EQ(std::string_view(drwav_version_string()), raw_DRWAV_VERSION_STRING);
    EXPECT_EQ(std::string_view(drflac_version_string()), raw_DRFLAC_VERSION_STRING);
    EXPECT_EQ(std::string_view(drmp3_version_string()), raw_DRMP3_VERSION_STRING);
}

